export const meta = {
  name: 'mm03-p2-final-review',
  description: 'Adversarial review of MM03 pass 2 module and report, with refuting judges',
  phases: [{ title: 'Find', detail: 'four lenses over module and report' }, { title: 'Judge', detail: 'one refuting judge per finding' }],
}
const S = '/private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad'
const CTX = `Context (read these files yourself):
- Task brief (French, binding arbitrages A1-A11): ${S}/task_mm03_p2.md
- Spec MM-03.3 v0.2: /Users/guygouri/Downloads/ERN_Memory_Model_0.3.3.md
- Lean module under review: /Users/guygouri/Devlab/ernlang/ern/formal/Ern/MM03.lean (namespace Ern.MM03, ~4400 lines)
- Report under review (French): /Users/guygouri/Devlab/ernlang/ern/formal/reports/MM03_v0.1_p2.md
- Pass-1 module for comparison: ${S}/p1.lean ; pass-1 report: /Users/guygouri/Devlab/ernlang/ern/formal/reports/MM03_v0.1.md
- Statement diff pass1 vs pass2: ${S}/p1p2_diff.txt
You are a read-only adversarial reviewer (AGENTS.md "Review" section applies to you). Never edit files under /Users/guygouri/Devlab/ernlang/ern. To test a claim in Lean, write a scratch file under ${S}/rev4/ starting with "import Ern.MM03" and "open Ern.MM03", and run it with: cd /Users/guygouri/Devlab/ernlang/ern/formal && ~/.elan/bin/lake env lean <absolute path>. Decidable predicates on concrete states can be checked with "by decide" (states can be built with enterEff, deriveEff, transferEff, etc., or as literal S3 structures; see the "Test cases" section of the module for examples).
Every finding needs evidence: a spec or brief quote, a Lean counterexample that you ran (give file path and output), or a quoted mismatch between report and code. No evidence, no finding. Do not ask for additions beyond the task. Report at most 8 findings, the most severe first; return an empty list if you find nothing real.`
const F = { type: 'object', properties: { findings: { type: 'array', items: { type: 'object', properties: {
  id: { type: 'string' }, severity: { type: 'string', enum: ['blocking', 'major', 'minor'] },
  location: { type: 'string' }, claim: { type: 'string' }, evidence: { type: 'string' },
  cause: { type: 'string', enum: ['formalization error', 'missing coverage', 'spec defect', 'report error'] } },
  required: ['id', 'severity', 'location', 'claim', 'evidence', 'cause'] } } }, required: ['findings'] }
const V = { type: 'object', properties: { real: { type: 'boolean' }, severity: { type: 'string', enum: ['blocking', 'major', 'minor', 'none'] }, reason: { type: 'string' }, evidence: { type: 'string' } }, required: ['real', 'severity', 'reason', 'evidence'] }
const LENSES = [
  { key: 'possession', prompt: `Lens: transfers, possession and dependencies (A4, A5, A6, A7). Hunt for Lean counterexamples: sequences of ok transitions (or single ok steps from states satisfying WF3 and Inv3) that end in an unsafe state, e.g. an active authority covering a leaf of a dead/freed/unusable place, an authority held by a dead holder staying active, a usable place with an inactive anchor, a value surviving its frame while anchored on a callee local, a root authority transferred alone, duplicated exclusive rights after transfer, owned storage escaping or being lost through transfer/endUse/free/exitFrame. Also check that each precondition says what A4-A8 say: not stronger, not weaker.` },
  { key: 'spec', prompt: `Lens: fidelity of definitions to the spec and to arbitrages A1-A11 (A2 Exercisable and where it is required, A3 parameters, A6 four distinct notions release/endUse/free/reset with the stated preconditions and effects, A8 pinning, A9 writeShared, A10 arena, A11 removed preconditions each with a redundancy theorem). Read definitions, hypotheses and quantifiers, not only proofs. Flag any definition more permissive or more restrictive than its rule, any silent interpretation of an unclear passage not reported in the report's (c) or (e), and any rule of the brief's steps 1-6 left without definition or theorem.` },
  { key: 'statements', prompt: `Lens: theorem statements. (1) The brief says every pass-1 statement that is rewritten is justified and none is weakened: compare ${S}/p1.lean with the module using ${S}/p1p2_diff.txt and the report's section (i); flag any weakening (added hypothesis, weaker conclusion, narrowed domain) without a valid justification, and check the justifications and the Lean witnesses they cite. (2) Check theorems that may hold vacuously or only because a definition is too permissive or hypotheses unsatisfiable. (3) Check docstrings that claim more than the statement.` },
  { key: 'report', prompt: `Lens: accuracy of the report against the code. Check the counts (theorems, examples, axioms), the tables of section (a), (h) (hypotheses of each listed theorem), the verdict table (g) against the examples of the "Test cases" and "Findings" sections, the claims of (d), (j), (k), (l), and every Lean name cited (it must exist and say what the report says). Run the checks you need (grep, Lean). Flag each wrong or unsupported claim with the exact report line.` },
]
phase('Find')
const results = await pipeline(LENSES,
  l => agent(`${CTX}\n\n${l.prompt}`, { label: `find:${l.key}`, phase: 'Find', schema: F }),
  (r, l) => parallel((r?.findings ?? []).map(f => () =>
    agent(`${CTX}\n\nYou are a judge. Try hard to REFUTE the following finding from the ${l.key} reviewer. Re-run any Lean evidence yourself. Mark real=false if the evidence does not hold, if the behaviour is what the spec/arbitrages require, if the report already discloses it as a decision (c) or question (e) with the exact behaviour, or if it asks for something beyond the task. If real, give the severity you assign.\n\nFINDING ${f.id} (${f.severity}, ${f.cause}) at ${f.location}:\n${f.claim}\nEvidence: ${f.evidence}`,
      { label: `judge:${l.key}:${f.id}`, phase: 'Judge', schema: V }).then(v => ({ lens: l.key, ...f, verdict: v }))))
)
const all = results.flat().filter(Boolean)
return { confirmed: all.filter(x => x.verdict?.real), refuted: all.filter(x => x.verdict && !x.verdict.real).map(x => ({ lens: x.lens, id: x.id, claim: x.claim, reason: x.verdict.reason })) }

